#include <iostream>
#include <vector>
#include <string>
#include <string>
using namespace std;

vector<int> prefixFunction(const string& s) {
    int n = (int)s.size();
    vector<int> pi(n, 0);
    for (int i = 1; i < n; i++) {
        int k = pi[i - 1];
        while (k > 0 && s[i] != s[k]) k = pi[k - 1];
        if (s[i] == s[k]) k++;
        pi[i] = k;
    }
    return pi;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string a;
    cin >> a;
    string b;
    cin >> b;

    bool found = false;
    if (a.size() == b.size()) {
        string c = b + "#" + a + a;
        vector<int> pi = prefixFunction(c);
        for (int v : pi) if (v == (int)b.size()) found = true;
    }
    cout << (found ? "YES" : "NO") << "\n";

    return 0;
}

